function literal(node,tree,depth=0){if(!node||depth>20)return undefined;if(ts.isStringLiteral(node)||ts.isNoSubstitutionTemplateLiteral(node))return node.text;if(ts.isNumericLiteral(node))return Number(node.text);if(node.kind===ts.SyntaxKind.TrueKeyword)return true;if(node.kind===ts.SyntaxKind.FalseKeyword)return false;if(ts.isArrayLiteralExpression(node)){const values=node.elements.map(value=>literal(value,tree,depth+1));return values.every(value=>value!==undefined)?values:undefined;}if(ts.isObjectLiteralExpression(node)){const object={};for(const property of node.properties){if(ts.isSpreadAssignment(property)){const spread=literal(property.expression,tree,depth+1);if(!spread)return undefined;Object.assign(object,spread);continue;}if(!ts.isPropertyAssignment(property))return undefined;const key=ts.isIdentifier(property.name)?property.name.text:literal(property.name,tree,depth+1);const value=literal(property.initializer,tree,depth+1);if(key===undefined||value===undefined)return undefined;object[key]=value;}return object;}if(ts.isBinaryExpression(node)&&node.operatorToken.kind===ts.SyntaxKind.PlusToken){const left=literal(node.left,tree,depth+1),right=literal(node.right,tree,depth+1);if(typeof left==='string'&&typeof right==='string')return left+right;}if(ts.isIdentifier(node)){for(let block=node.parent;block;block=block.parent){for(const statement of block.statements??[]){if(statement.pos>node.pos)continue;if(ts.isVariableStatement(statement))for(const declaration of statement.declarationList.declarations)if(declaration.name.getText(tree)===node.text)return literal(declaration.initializer,tree,depth+1);}}}if(ts.isCallExpression(node)&&node.expression.getText(tree)==='JSON.stringify'){const value=literal(node.arguments[0],tree,depth+1);if(value!==undefined)return JSON.stringify(value);}}
for(const filename of ['ui-steps-cross-tier.test.ts','test-request-edges.test.ts']){
 const tree=ts.createSourceFile(filename,readFileSync(join(root,'__tests__',filename),'utf8'),ts.ScriptTarget.Latest,true);const files={};
 function visit(node){if(ts.isCallExpression(node)){const name=node.expression.getText(tree);if(name==='write'){const path=literal(node.arguments[0],tree),source=literal(node.arguments[1],tree);if(typeof path==='string'&&typeof source==='string')files[path]=source;}if(name==='indexed'){const input=literal(node.arguments[0],tree);if(input&&typeof input==='object')projects.push({id:`requests-${projects.length}`,files:input,origin:filename});}}ts.forEachChild(node,visit);}visit(tree);if(Object.keys(files).length)projects.push({id:'tier-original',files,origin:filename});
}
