for(const project of projects){const directory=mkdtempSync(join(tmpdir(),'prometeu-tier-'));let indexed;try{
 for(const [path,source]of Object.entries(project.files)){mkdirSync(dirname(join(directory,path)),{recursive:true});writeFileSync(join(directory,path),source);}
 indexed=await Project.init(directory,{silent:true});await indexed.indexAll();const resolver=new ReferenceResolver(directory,indexed.queries);resolver.initialize();
 project.nodes=indexed.queries.getAllNodes();project.imports=[];
 for(const file of resolver.context.getAllFiles()){const node=resolver.context.getNodesInFile(file).find(node=>node.kind==='file');if(!node)continue;for(const binding of resolver.context.getImportMappings(file,node.language))project.imports.push({file,local_name:binding.localName,source:binding.source,imported_name:binding.exportedName,is_namespace:binding.isNamespace??false,is_default:binding.isDefault??false,mapped_path:binding.resolvedPath??null,resolved_path:resolveImportPath(binding.source,file,node.language,resolver.context)??null,external:resolver.context.isOutOfRepoImport?.(binding.source,file,node.language)===true});}
 project.expected={cross:await crossTierEdges(resolver.context,async()=>{}),requests:await testRequestEdges(resolver.context,async()=>{})};for(const node of project.nodes)delete node.updatedAt;console.log(project.id,project.expected.cross.length,project.expected.requests.length);
}finally{indexed?.close();rmSync(directory,{recursive:true,force:true});}}
